namespace Spatie\Permission\Traits;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\MorphToMany;
use Illuminate\Support\Arr;
use Illuminate\Support\Collection;
use Illuminate\Support\Facades\DB;
use Spatie\Permission\PermissionRegistrar;
use Spatie\Permission\Support\Config;

/**
 * Provides bulk model-assignment operations from the role's side, mirroring the
 * per-model helpers offered by the HasRoles trait (assignRole/removeRole/syncRoles).
 */
trait HasAssignedModels
{
    /**
     * Assign this role to the given models without removing existing assignments.
     *
     * Accepts a single model, a single id, or an array/collection of models and/or ids.
     * Already-assigned models are not re-inserted, so the operation is idempotent and
     * deduplicates its inputs.
     *
     * @param  array|Collection|Model|int|string  $models
     * @return $this
     */
    public function assignToModels($models, ?string $modelClass = null): static
    {
        foreach ($this->parseAssignedModels($models, $modelClass) as $class => $ids) {
            $this->assignedModels($class)->syncWithoutDetaching($this->withTeamPivot($ids));
        }

        return $this;
    }

    /**
     * Remove this role from the given models, leaving all other assignments intact.
     *
     * Accepts a single model, a single id, or an array/collection of models and/or ids.
     * Removing a model that does not have the role is a no-op.
     *
     * @param  array|Collection|Model|int|string  $models
     * @return $this
     */
    public function removeFromModels($models, ?string $modelClass = null): static
    {
        foreach ($this->parseAssignedModels($models, $modelClass) as $class => $ids) {
            $this->assignedModels($class)->detach($ids);
        }

        return $this;
    }

    /**
     * Replace ALL existing model assignments for this role with the given set.
     *
     * Accepts a single model, a single id, or an array/collection of models and/or ids.
     * An empty array or collection removes every existing assignment. Inputs are
     * deduplicated so no duplicate pivot records are created.
     *
     * @param  array|Collection|Model|int|string  $models
     * @return $this
     */
    public function syncModels($models, ?string $modelClass = null): static
    {
        $grouped = $this->parseAssignedModels($models, $modelClass);

        // Wipe every existing association for this role before re-attaching the new set.
        $this->clearAssignedModels();

        foreach ($grouped as $class => $ids) {
            $this->assignedModels($class)->attach($this->withTeamPivot($ids));
        }

        return $this;
    }

    /**
     * Build the inverse morph relation used to attach/detach the given model class.
     */
    protected function assignedModels(string $modelClass): MorphToMany
    {
        return $this->morphedByMany(
            $modelClass,
            'model',
            Config::modelHasRolesTable(),
            app(PermissionRegistrar::class)->pivotRole,
            Config::morphKey()
        );
    }

    /**
     * Normalise the given input into an array of [modelClass => [ids...]] groups,
     * deduplicating ids within each class.
     *
     * @param  array|Collection|Model|int|string  $models
     */
    protected function parseAssignedModels($models, ?string $modelClass): array
    {
        if ($models instanceof Collection) {
            $models = $models->all();
        }

        $grouped = [];

        foreach (Arr::wrap($models) as $model) {
            if ($model === null || $model === '') {
                continue;
            }

            if ($model instanceof Model) {
                $class = $model::class;
                $id = $model->getKey();
            } else {
                $class = $modelClass ?? config('permission.models.default_model');
                $id = $model;
            }

            $grouped[$class] ??= [];

            if (! in_array($id, $grouped[$class])) {
                $grouped[$class][] = $id;
            }
        }

        return $grouped;
    }

    /**
     * Format the given ids for attaching, adding the team pivot value when teams are enabled.
     */
    protected function withTeamPivot(array $ids): array
    {
        if (! Config::teamsEnabled()) {
            return $ids;
        }

        $teamPivot = [Config::teamForeignKey() => getPermissionsTeamId()];

        return collect($ids)->mapWithKeys(fn ($id) => [$id => $teamPivot])->all();
    }

    /**
     * Remove every model association for this role (scoped to the current team when enabled).
     */
    protected function clearAssignedModels(): void
    {
        $query = DB::table(Config::modelHasRolesTable())
            ->where(app(PermissionRegistrar::class)->pivotRole, $this->getKey());

        if (Config::teamsEnabled()) {
            $query->where(Config::teamForeignKey(), getPermissionsTeamId());
        }

        $query->delete();
    }
